#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    long long basis[60] = {0};
    for (long long x : a) {
        for (int bit = 59; bit >= 0; bit--) {
            if (!((x >> bit) & 1)) continue;
            if (basis[bit] == 0) {
                basis[bit] = x;
                break;
            }
            x ^= basis[bit];
        }
    }
    long long res = 0;
    for (int bit = 59; bit >= 0; bit--) {
        if ((res ^ basis[bit]) > res) res ^= basis[bit];
    }
    cout << res << "\n";

    return 0;
}

